/**
 * expressive-figma.mjs — generate the 5 generic Expressive (Scope) accent
 * ramps and emit them as Figma-ready hex.
 *
 * 5 accent slots (accent1..accent5), default hues spaced 20° apart in OKLCH
 * starting at base 25 → 25, 45, 65, 85, 105 (editable defaults). Each slot is
 * a full 50…950 ramp generated by the SAME `hueToRamp` engine the themes use,
 * converted to sRGB hex by the SAME CSS Color 4 pipeline as themes-to-figma.mjs
 * (so values are byte-identical to the in-app browser converter).
 *
 * Output: expressive-figma.json = { "accent1": {"50":"#..",…,"950":"#.."}, … }
 *
 * Run (from apps/docs):
 *   node --experimental-strip-types --loader ./scripts/_ts-resolve-hook.mjs \
 *     scripts/expressive-figma.mjs
 */

import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import { hueToRamp, RAMP_KEYS } from "../lib/themes/oklch.ts";

const __dirname = dirname(fileURLToPath(import.meta.url));

/* ─────────────────────── OKLCH → sRGB hex ───────────────────────
   Copied verbatim from themes-to-figma.mjs — CSS Color 4 reference pipeline
   with the gamut-mapping (MINDE) algorithm + final 0–255 clamp. Matches the
   in-app getComputedStyle-based converter (proven by that script's Calm test). */

function oklabToLinearSrgb(L, a, b) {
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b;
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b;
  const s_ = L - 0.0894841775 * a - 1.291485548 * b;
  const l = l_ * l_ * l_;
  const m = m_ * m_ * m_;
  const s = s_ * s_ * s_;
  return [
    +4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s,
  ];
}

function linearToSrgb(c) {
  const sign = c < 0 ? -1 : 1;
  const abs = Math.abs(c);
  if (abs > 0.0031308) return sign * (1.055 * Math.pow(abs, 1 / 2.4) - 0.055);
  return 12.92 * c;
}

function linearSrgbToOklab(r, g, b) {
  const l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
  const m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
  const s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b;
  const l_ = Math.cbrt(l);
  const m_ = Math.cbrt(m);
  const s_ = Math.cbrt(s);
  return [
    0.2104542553 * l_ + 0.793617785 * m_ - 0.0040720468 * s_,
    1.9779984951 * l_ - 2.428592205 * m_ + 0.4505937099 * s_,
    0.0259040371 * l_ + 0.7827717662 * m_ - 0.808675766 * s_,
  ];
}

function oklchToLinearSrgb(L, C, Hdeg) {
  const h = (Hdeg * Math.PI) / 180;
  return oklabToLinearSrgb(L, C * Math.cos(h), C * Math.sin(h));
}

const inGamut = (rgb) => rgb.every((c) => c >= -1e-4 && c <= 1 + 1e-4);
const clipLinear = (rgb) => rgb.map((c) => Math.min(1, Math.max(0, c)));

function oklchToHex(triplet) {
  const parts = String(triplet).trim().split(/\s+/).map(Number);
  if (parts.length < 3 || parts.some(Number.isNaN)) return "";
  const [L, C, Hdeg] = parts;

  let linear = oklchToLinearSrgb(L, C, Hdeg);

  if (!inGamut(linear)) {
    const JND = 0.02;
    const EPS = 0.0001;
    let lo = 0;
    let hi = C;
    let result = clipLinear(linear);
    while (hi - lo > EPS) {
      const mid = (lo + hi) / 2;
      const candidate = oklchToLinearSrgb(L, mid, Hdeg);
      if (inGamut(candidate)) {
        lo = mid;
        result = clipLinear(candidate);
      } else {
        const clipped = clipLinear(candidate);
        const [l1, a1, b1] = linearSrgbToOklab(...clipped);
        const [l2, a2, b2] = linearSrgbToOklab(...candidate);
        const dE = Math.hypot(l1 - l2, a1 - a2, b1 - b2);
        if (dE < JND) {
          result = clipped;
          break;
        }
        hi = mid;
      }
    }
    linear = result;
  }

  const r = linearToSrgb(linear[0]);
  const g = linearToSrgb(linear[1]);
  const bl = linearToSrgb(linear[2]);
  const toByte = (x) => Math.max(0, Math.min(255, Math.round(x * 255)));
  return (
    "#" +
    [toByte(r), toByte(g), toByte(bl)]
      .map((x) => x.toString(16).padStart(2, "0"))
      .join("")
      .toUpperCase()
  );
}

/* ─────────────────────── build the 5 accents ─────────────────────── */

const BASE_HUE = 25;
const STEP_DEG = 20;
const ACCENT_COUNT = 5;

const accents = {};
const five00 = [];
for (let i = 0; i < ACCENT_COUNT; i++) {
  const hue = BASE_HUE + i * STEP_DEG;
  const ramp = hueToRamp({ hue }); // default chromaScale 1, lightnessShift 0
  const slot = `accent${i + 1}`;
  const out = {};
  for (const step of RAMP_KEYS) {
    out[String(step)] = oklchToHex(ramp[step]);
  }
  accents[slot] = out;
  five00.push({ slot, hue, hex: out["500"] });
}

const outPath = join(__dirname, "expressive-figma.json");
writeFileSync(outPath, JSON.stringify(accents, null, 2) + "\n", "utf8");

console.log("Expressive accents — base hue", BASE_HUE, "step", STEP_DEG + "°");
console.log("=".repeat(48));
for (const { slot, hue, hex } of five00) {
  console.log(`${slot}  hue ${String(hue).padStart(3)}°  500 → ${hex}`);
}
console.log("=".repeat(48));
console.log("Output:", outPath);
